if(e.pointerType==="touch"){
  if(!touchPointers.has(e.pointerId))return;
  e.preventDefault();
  const ended=touchPointers.get(e.pointerId);
  const wasOnly=touchPointers.size===1;
  const canTap=wasOnly && !touchHadPinch && !touchMoved && Math.hypot(ended.x-ended.startX,ended.y-ended.startY)<10;
  touchPointers.delete(e.pointerId);
  if(canTap)activateMapAt(e.clientX,e.clientY);
  if(touchPointers.size===1){beginSingleTouch(pointerArray()[0]);touchHadPinch=true;}
  else if(touchPointers.size===0){touchGesture="";touchHadPinch=false;touchMoved=false;}
  return;
}

if(e.pointerType==="touch"){
  if(!touchPointers.has(e.pointerId))return;
  e.preventDefault();
  const p=touchPointers.get(e.pointerId);p.x=e.clientX;p.y=e.clientY;
  if(touchPointers.size>=2){
    if(touchGesture!=="pinch")beginPinch();
    const pts=pointerArray(),a=pts[0],b=pts[1],mid=pointerMid(a,b);
    const ratio=pointerDistance(a,b)/Math.max(1,pinchStartDistance);
    zoom=Math.max(0.72,Math.min(5.0,pinchStartZoom*ratio));
    const ns=scale();panX=mid.x-pinchWorldX*ns;panY=mid.y-pinchWorldY*ns;
    clampPan();applyTransform();
  }else if(touchPointers.size===1 && touchGesture==="pan"){
    const only=pointerArray()[0];
    const dx=only.x-touchPanOriginX,dy=only.y-touchPanOriginY;
    if(Math.hypot(dx,dy)>6)touchMoved=true;
    panX=touchPanStartX+dx;panY=touchPanStartY+dy;clampPan();applyTransform();
  }
  return;
}

const p=localPoint(e.clientX,e.clientY),x=p.x,y=p.y;
if(!dragging){
  const hit=[...hitboxes].reverse().find(h=>x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h);
  const newHover=hit?hit.id:"";
  if(newHover!==hovered){hovered=newHover;viewport.style.cursor=hovered?"pointer":"default";draw();}
