// --- Souris + téléphone : pan 1 doigt, pinch 2 doigts, tap sur les points ---
const touchPointers=new Map();
let touchGesture="", touchHadPinch=false, touchMoved=false;
let touchPanOriginX=0,touchPanOriginY=0,touchPanStartX=0,touchPanStartY=0;
let pinchStartDistance=1,pinchStartZoom=1,pinchWorldX=0,pinchWorldY=0;

function localPoint(clientX,clientY){
  const r=viewport.getBoundingClientRect(),s=scale();
  return {x:(clientX-r.left-panX)/s,y:(clientY-r.top-panY)/s,rx:clientX-r.left,ry:clientY-r.top};
}
function activateMapAt(clientX,clientY){
  const p=localPoint(clientX,clientY),x=p.x,y=p.y;
  const chit=[...casualtyHitboxes].reverse().find(h=>x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h);
  if(chit){selectCasualty(chit.id);return;}
  const storyHit=[...storyHitboxes].reverse().find(h=>x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h);
  if(storyHit){selectStory(storyHit.id);return;}
  const hit=[...hitboxes].reverse().find(h=>x>=h.x&&x<=h.x+h.w&&y>=h.y&&y<=h.y+h.h);
  if(hit){selectUnit(hit.id);return;}
  if(coordMode){
    const c=el("coord");c.textContent=`X ${Math.round(x)} • Y ${Math.round(y)}`;
    c.style.left=(x+12)+"px";c.style.top=(y+12)+"px";c.style.display="block";
  }
}
function pointerArray(){return [...touchPointers.values()]}
function pointerDistance(a,b){return Math.hypot(b.x-a.x,b.y-a.y)}
function pointerMid(a,b){
  const r=viewport.getBoundingClientRect();
  return {x:(a.x+b.x)/2-r.left,y:(a.y+b.y)/2-r.top};
}
function beginSingleTouch(p){
  touchGesture="pan";touchMoved=false;
  touchPanOriginX=p.x;touchPanOriginY=p.y;
  touchPanStartX=panX;touchPanStartY=panY;
}
function beginPinch(){
  const pts=pointerArray(); if(pts.length<2)return;
  const a=pts[0],b=pts[1],mid=pointerMid(a,b),s=scale();
  touchGesture="pinch";touchHadPinch=true;touchMoved=true;
  pinchStartDistance=Math.max(12,pointerDistance(a,b));
  pinchStartZoom=zoom;
  pinchWorldX=(mid.x-panX)/s;pinchWorldY=(mid.y-panY)/s;
}

el("musicMenuBtn").addEventListener("click",toggleMusicMenu);
el("musicChoiceMenu").addEventListener("click",(ev)=>{
  const b=ev.target.closest("[data-music-index]");
  if(b)selectMusicTrack(b.dataset.musicIndex);
  ev.stopPropagation();
});
document.addEventListener("click",(ev)=>{
  const split=el("musicSplit"), menu=el("musicChoiceMenu");
  if(menu&&menu.classList.contains("open")&&!menu.contains(ev.target)&&!(split&&split.contains(ev.target)))closeMusicMenu();
});
window.addEventListener("resize",()=>{if(el("musicChoiceMenu")?.classList.contains("open"))positionMusicMenu();});
window.addEventListener("scroll",()=>{if(el("musicChoiceMenu")?.classList.contains("open"))positionMusicMenu();},true);
